  int _handle;
  bool _closed = false;

  static final Finalizer<_CancellationHandleFinalizerToken> _finalizer = Finalizer((token) {
    token.free(token.handle);
  });

  bool get isClosed => _closed;

  void close() {
    if (_closed) {
      return;
    }
    _closed = true;
    _finalizer.detach(this);
    _ffi._cancellationHandleFree(_handle);
  }

  void _ensureOpen() {
    if (_closed) {
      throw StateError('CancellationHandle is closed');
    }
  }

  /// Creates a fresh, one-shot cancellation handle.
  static CancellationHandle create() {
    return _bindings().cancellationHandleCreateNew();
  }

  /// Cancels the Rust-owned operation associated with this handle.
  void cancel() {
    _ensureOpen();
    _ffi.cancellationHandleInvokeCancel(_handle);
  }

  /// Returns whether cancellation has been requested.
  bool isCancelled() {
    _ensureOpen();
    return _ffi.cancellationHandleInvokeIsCancelled(_handle);
  }

}

final class CancellationHandleFfiCodec {
  const CancellationHandleFfiCodec._();

  static int lower(CancellationHandle value) => value._handle;

  static CancellationHandle lift(int handle) => CancellationHandle._(_bindings(), handle);
}

AcyclicActorsUniffiFfi? _defaultBindings;

AcyclicActorsUniffiFfi _bindings() => _defaultBindings ??= AcyclicActorsUniffiFfi();

void configureDefaultBindings({ffi.DynamicLibrary? dynamicLibrary, String? libraryPath}) {
  _defaultBindings = AcyclicActorsUniffiFfi(dynamicLibrary: dynamicLibrary, libraryPath: libraryPath);
}

void resetDefaultBindings() {
  _defaultBindings = null;
}

/// Connects through the canonical Rust transport and returns an opaque client.
Future<ActorsClient> connectActors(String endpoint, String token, CancellationHandle? cancellation) {
  return _bindings().connectActors(endpoint, token, cancellation);
}

/// Connects with an optional caller-pinned CA certificate.
Future<ActorsClient> connectActorsWithCa(String endpoint, String token, Uint8List? caCertificate, CancellationHandle? cancellation) {
  return _bindings().connectActorsWithCa(endpoint, token, caCertificate, cancellation);
}

